<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {BookOpen,FileBadge,Building2,Plane,ArrowRight,UserRound,Download,Check,Save,GraduationCap,Plus} from '@lucide/vue'
import type {ApiResult,Player,Project,RoomState,Work} from '../types'
import content from '../content.json'
import ResearchRewards from './ResearchRewards.vue'
import ContractPanel from './ContractPanel.vue'
import ScholarPortrait from './ScholarPortrait.vue'
const props=defineProps<{player:Player;state:RoomState;busy:boolean;now:number;perform:(action:string,payload?:Record<string,unknown>)=>Promise<ApiResult|undefined>}>()
const emit=defineEmits<{map:[]}>()
const section=ref<'desk'|'contracts'|'outputs'|'resume'>('desk'),workFilter=ref<'papers'|'patents'>('papers')
const title=ref(props.player.paper.title||''),studentIds=ref<string[]>([...(props.player.paper.collaborators?.studentIds||[])]),withPartner=ref(!!props.player.paper.collaborators?.partner),dirty=ref(false)
const profileName=ref(props.player.profile.name),research=ref(props.player.profile.research),bio=ref(props.player.profile.bio),editingProfile=ref(false),repIds=ref<string[]>([...props.player.representatives])
const representativesDirty=ref(false)
const partner=computed(()=>Object.values(props.state.players).find(p=>p.id!==props.player.id))
const projects=computed(()=>Object.values(props.state.projects).filter(pr=>pr.owner===props.player.id))
const contractCount=computed(()=>Object.values(props.state.projects).filter(pr=>pr.contract&&!pr.completedAt&&(pr.owner===props.player.id||pr.contract.steps.some(st=>st.job?.partnerId===props.player.id))).length)
const activeProjects=computed(()=>projects.value.filter(pr=>!pr.completedAt).length)
const target=computed(()=>['major','minor'].includes(props.player.paper.phase)?props.player.paper.required:100)
const paperLabel=computed(()=>({review:'Under Review · 审稿人正在路上',major:'Major Revision · 把问题拆小慢慢来',minor:'Minor Revision · 离完成更近了',draft:props.player.paper.title||'手头的那篇论文'})[props.player.paper.phase])
const representatives=computed(()=>props.player.representatives.map(id=>props.player.portfolio.papers.find(w=>w.id===id)).filter((w):w is Work=>!!w))
const allWorks=computed(()=>[...props.player.portfolio[workFilter.value]].reverse())
const currentStudents=computed(()=>props.player.students.filter(st=>!st.graduatedAt))
const date=(at:number)=>at?new Date(at).toLocaleDateString('zh-CN'):'历史成果'
const duration=(ms:number)=>Math.max(0,Math.ceil(ms/60000))+' 分钟'
const money=(n:number)=>Math.floor(n).toLocaleString()
function finance(pr:Project){return pr.finance||{model:'facility',totalFunding:0,advance:0,initialInvestment:content.projects[pr.def]?.cost||0,receivedFunding:0,operatingIncome:0,allocatedFunding:0,workCosts:0,partnerPaid:0}}
async function saveDraft(){const r=await props.perform('paper_configure',{title:title.value,studentIds:studentIds.value,partner:withPartner.value});if(r?.ok)dirty.value=false;return r}
async function submit(){if(props.player.paper.phase!=='review'){const r=await saveDraft();if(r?.ok)await props.perform('submit')}}
watch(()=>props.player.paper.title,()=>{if(!dirty.value){title.value=props.player.paper.title||'';studentIds.value=[...(props.player.paper.collaborators?.studentIds||[])];withPartner.value=!!props.player.paper.collaborators?.partner}})
watch(()=>props.player.representatives,()=>{if(!representativesDirty.value)repIds.value=[...props.player.representatives]})
function toggleRepresentative(id:string){representativesDirty.value=true;repIds.value=repIds.value.includes(id)?repIds.value.filter(x=>x!==id):repIds.value.length<5?[...repIds.value,id]:repIds.value}
async function saveRepresentatives(){const ids=[...repIds.value],r=await props.perform('representatives',{ids});if(r?.ok){representativesDirty.value=false;repIds.value=[...ids]}}
async function saveProfile(){const r=await props.perform('profile_update',{name:profileName.value,research:research.value,bio:bio.value});if(r?.ok)editingProfile.value=false}
const esc=(v:unknown)=>String(v??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;')
function downloadCV(){
 const p=props.player,list=(arr:Work[])=>arr.map(w=>'<li><b>'+esc(w.title)+'</b><br>'+esc(w.authors.map(a=>a.name).join('、'))+' · '+esc(w.number||w.journal)+' · '+esc(date(w.publishedAt))+'</li>').join('')
 const body='<p class="fiction">不急大学 · 游戏科研履历（虚构游戏资料）</p><h1>'+esc(p.profile.name)+'</h1><p>'+esc(p.profile.school)+'｜'+esc(p.profile.research)+'</p><p>'+esc(p.profile.bio)+'</p><p>论文 '+p.papers+' 篇 · 专利 '+p.patent.total+' 项 · 项目 '+projects.value.length+' 项 · 在组学生 '+currentStudents.value.length+' 位</p><h2>代表作</h2><ol>'+list(representatives.value)+'</ol><h2>科研项目</h2><ul>'+projects.value.map(pr=>{const f=finance(pr);return '<li>'+esc(content.projects[pr.def]?.name)+'：'+(f.model==='contract'?'横向总经费 '+money(f.totalFunding)+'，已到账 '+money(f.receivedFunding):'设施投入 '+money(f.initialInvestment)+'，累计经营收益 '+money(f.operatingIncome))+'</li>'}).join('')+'</ul><h2>授权专利</h2><ol>'+list(p.portfolio.patents)+'</ol><h2>学术经历</h2><ul>'+p.portfolio.activities.filter(a=>a.status==='completed').map(a=>'<li>'+esc(a.title)+' · '+esc(a.venue)+' · '+esc(date(a.at))+'</li>').join('')+'</ul><h2>学生与培养规划</h2>'+p.students.map(st=>'<section><h3>'+esc(st.name)+' · '+(st.degree==='masters'?'硕士':'博士')+' · '+esc(st.topic)+'</h3><p>'+esc(st.plan)+'</p><p>当前任务：'+esc(st.task?.title||'自由研究')+'；论文 '+st.paper.total+'，专利 '+st.patent.total+'</p><ul>'+st.activities.filter(a=>a.status==='completed').map(a=>'<li>'+esc(a.title)+' · '+esc(a.venue)+'</li>').join('')+'</ul></section>').join('')
 const html='<!doctype html><html lang="zh-CN"><meta charset="utf-8"><title>'+esc(p.profile.name)+'的游戏科研履历</title><style>body{font:15px/1.9 system-ui,sans-serif;max-width:850px;margin:50px auto;padding:0 25px;color:#263647}h1{font-size:32px}h2{border-bottom:1px solid #dce4ee;padding-top:18px}li{margin:12px 0}.fiction{color:#9b6f56;font-size:12px}section{break-inside:avoid}@media print{body{margin:0}h2{break-after:avoid}}</style>'+body+'</html>'
 const url=URL.createObjectURL(new Blob([html],{type:'text/html;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=p.profile.name+'-不急大学游戏科研履历.html';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)
}
</script>
<template>
 <div class="panel-heading"><div><span class="eyebrow">BUJI UNIVERSITY · RESEARCH & CV</span><h1>我的科研</h1></div><BookOpen :size="30"/></div><div class="research-subnav"><button :class="{active:section==='desk'}" @click="section='desk'"><BookOpen :size="15"/>科研工作台</button><button :class="{active:section==='contracts'}" @click="section='contracts'"><Building2 :size="15"/>横向任务<span v-if="contractCount" class="contract-tab-count">{{ contractCount }}</span></button><button :class="{active:section==='outputs'}" @click="section='outputs'"><FileBadge :size="15"/>课题组成果</button><button :class="{active:section==='resume'}" @click="section='resume'"><UserRound :size="15"/>我的简历</button></div>
 <template v-if="section==='desk'"><button v-if="contractCount" class="contract-desk-link" @click="section='contracts'"><Building2 :size="19"/><span>{{ contractCount }} 份横向待推进 · 安排执行、接受合作或提交验收</span><ArrowRight :size="17"/></button><ResearchRewards :player="player" :busy="busy" :now="now" :lab-level="state.lab.level" @act="perform"/>
  <article class="paper-feature"><span class="small-label">当前稿件</span><h2>{{ paperLabel }}</h2><p>{{ player.paper.phase==='review'?'审稿期间获得的新进度会进入下一篇灵感箱。':'给稿件定一个题目，选好共同作者，再一点点推进研究。' }}</p><div class="progress-track"><i :style="{width:Math.min(100,player.paper.progress/target*100)+'%'}"/></div><div class="paper-summary"><span>{{ player.paper.progress }} / {{ target }} · 灵感箱 {{ player.paper.bank }} / 60</span><button class="primary" :disabled="busy||player.paper.phase==='review'||player.paper.progress<target" @click="submit">{{ player.paper.phase==='review'?'Under Review':player.paper.phase==='draft'?'投稿':'提交返修稿' }}<ArrowRight :size="16"/></button></div>
   <form class="manuscript-form" @submit.prevent="saveDraft"><label>虚拟论文题目<input v-model="title" maxlength="120" :disabled="player.paper.phase==='review'" placeholder="留空时根据方向自动生成" @input="dirty=true"/></label><div class="author-options"><span>作者：{{ player.profile.name }}（导师）</span><label v-for="st in player.students" :key="st.id" class="check-label"><input v-model="studentIds" type="checkbox" :value="st.id" :disabled="player.paper.phase==='review'||studentIds.length>=2&&!studentIds.includes(st.id)" @change="dirty=true"/>{{ st.name }}</label><label v-if="partner" class="check-label"><input v-model="withPartner" type="checkbox" :disabled="player.paper.phase==='review'" @change="dirty=true"/>{{ partner.profile.name }}（合作）</label></div><button class="secondary" :disabled="busy||player.paper.phase==='review'"><Save :size="14"/>保存题目与作者</button></form>
  </article><div class="section-title"><h2>我的项目与设施</h2><span>{{ activeProjects }} / 3 个进行中</span></div><div v-if="!projects.length" class="empty-state"><Building2 :size="34"/><h3>横向课题带来经费，设施提供长期支持。</h3><p>走到对应地点可以签合同或建设设施；两类项目会分开记账。</p><button class="text-button" @click="emit('map')">去园区转转<ArrowRight :size="15"/></button></div><article v-for="pr in projects" :key="pr.def" class="project-finance-row"><div class="finance-head"><span class="finance-icon" :class="finance(pr).model"><component :is="content.projects[pr.def]?.domain==='air'?Plane:Building2" :size="23"/></span><div><span class="small-label">{{ finance(pr).model==='contract'?'横向科研合同':finance(pr).legacy?'旧版建设设施':'建设与共享设施' }}</span><h3>{{ content.projects[pr.def]?.name }}</h3></div><b class="finance-status">{{ pr.completedAt?'合同已完成':'进行中' }}</b></div><div class="finance-numbers"><span>{{ finance(pr).model==='contract'?'合同总经费':'初始建设投入' }}<b>{{ money(finance(pr).model==='contract'?finance(pr).totalFunding:finance(pr).initialInvestment) }}</b></span><span>{{ finance(pr).model==='contract'?'执行支出':'累计经营收入' }}<b>{{ money(finance(pr).model==='contract'?(finance(pr).workCosts||0):finance(pr).operatingIncome) }}</b></span><span>{{ finance(pr).model==='contract'?'累计到账':'基础每阶段收入' }}<b>{{ money(finance(pr).model==='contract'?finance(pr).receivedFunding:content.projects[pr.def]!.income) }}</b></span></div><p v-if="finance(pr).model==='contract'">{{ pr.completedAt?'合同已结项。':'横向不再被动发钱；完成阶段任务后提交验收，才按合同预算拨款。' }}<button class="text-button" @click="section='contracts'">查看横向任务<ArrowRight :size="13"/></button></p><p v-else>每 2 小时结算一阶段，仓储 {{ pr.stock.length }} / 6；{{ duration(2*3600000-pr.elapsed) }}后到下一阶段。</p></article>
 </template>
 <template v-else-if="section==='contracts'"><ContractPanel :player="player" :state="state" :busy="busy" :now="now" :perform="perform"/></template><template v-else-if="section==='outputs'"><div class="outputs-overview"><div><b>{{ player.papers }}</b><span>课题组累计论文</span></div><div><b>{{ player.patent.total }}</b><span>累计授权专利</span></div><div><b>{{ player.representatives.length }} / 5</b><span>已选代表作</span></div></div><div class="section-title"><div class="output-switch"><button :class="{active:workFilter==='papers'}" @click="workFilter='papers'">论文档案</button><button :class="{active:workFilter==='patents'}" @click="workFilter='patents'">专利档案</button></div><button v-if="workFilter==='papers'" class="secondary" :disabled="busy" @click="saveRepresentatives"><Save :size="14"/>保存代表作（{{ repIds.length }} / 5）</button></div><p v-if="workFilter==='papers'" class="muted">从已发表论文中选择最多 5 篇放入个人简历。学生独立完成、师生合作及与 {{ partner?.profile.name||'搭子' }} 合作的论文都会保留作者。</p><article v-for="w in allWorks" :key="w.id" class="publication-row"><label v-if="workFilter==='papers'" class="representative-check"><input type="checkbox" :checked="repIds.includes(w.id)" :disabled="busy||repIds.length>=5&&!repIds.includes(w.id)" @change="toggleRepresentative(w.id)"/><span>代表作</span></label><FileBadge v-else :size="22"/><div><span class="work-origin">{{ w.source==='student'?'学生任务成果':w.source==='legacy'?'历史成果':'研究成果' }}</span><h3>{{ w.title }}</h3><p>{{ w.authors.map(a=>a.name).join('、') }}</p><small>{{ w.journal||w.number }} · {{ date(w.publishedAt) }}</small></div><span class="work-status">{{ w.number?'已授权':'已发表' }}</span></article><div v-if="!allWorks.length" class="empty-state"><BookOpen :size="32"/><p>第一项成果还在路上。自己的稿件和学生任务完成后，会生成有标题、有作者的成果记录。</p></div></template>
 <template v-else><div class="resume-toolbar"><span>不急大学 · 游戏科研履历</span><div><button class="secondary" @click="editingProfile=!editingProfile">编辑介绍</button><button class="primary" @click="downloadCV"><Download :size="15"/>下载简历</button></div></div><form v-if="editingProfile" class="profile-edit-form" @submit.prevent="saveProfile"><label>姓名 / 署名<input v-model="profileName" maxlength="24" required/></label><label>研究方向<input v-model="research" maxlength="200" required/></label><label>个人介绍<textarea v-model="bio" rows="3" maxlength="500"/></label><button class="primary" :disabled="busy"><Save :size="15"/>保存介绍</button></form><article class="research-resume"><header><div><span>BUJI UNIVERSITY</span><h1>{{ player.profile.name }}</h1><p>{{ player.profile.school }} · {{ player.discipline==='civil'?'智能建造课题组':'低空经济课题组' }}</p></div><ScholarPortrait :seed="player.id" :size="84" :label="player.profile.name+'头像'"/></header><p class="resume-directions">{{ player.profile.research }}</p><p class="resume-bio">{{ player.profile.bio }}</p><div class="resume-facts"><span>已发表论文<b>{{ player.papers }}</b></span><span>授权专利<b>{{ player.patent.total }}</b></span><span>承接项目<b>{{ projects.length }}</b></span><span>在组学生<b>{{ currentStudents.length }}</b></span></div>
   <section><h2>代表性论文 <small>{{ representatives.length }} / 5</small></h2><ol class="resume-publications"><li v-for="w in representatives" :key="w.id"><h3>{{ w.title }}</h3><p>{{ w.authors.map(a=>a.name).join('、') }} · {{ w.journal }} · {{ date(w.publishedAt) }}</p></li></ol><p v-if="!representatives.length" class="empty-note">在“课题组成果”中选择至多五篇代表作。</p></section>
   <section><h2>科研项目与经费</h2><div class="resume-projects"><article v-for="pr in projects" :key="pr.def"><h3>{{ content.projects[pr.def]?.name }}</h3><p v-if="finance(pr).model==='contract'">横向合同 · 总经费 {{ money(finance(pr).totalFunding) }} · 已到账 {{ money(finance(pr).receivedFunding) }} · 执行支出 {{ money(finance(pr).workCosts||0) }} · 搭子分账 {{ money(finance(pr).partnerPaid||0) }}</p><p v-else>建设设施 · 已投入 {{ money(finance(pr).initialInvestment) }} · 经营收入 {{ money(finance(pr).operatingIncome) }}</p></article></div><p v-if="!projects.length" class="empty-note">尚未承接项目。</p></section>
   <section><h2>授权专利</h2><ol class="resume-publications"><li v-for="w in player.portfolio.patents" :key="w.id"><h3>{{ w.title }}</h3><p>{{ w.authors.map(a=>a.name).join('、') }} · {{ w.number }} · {{ date(w.publishedAt) }}</p></li></ol><p v-if="!player.portfolio.patents.length" class="empty-note">授权成果将自动归档。</p></section>
   <section><h2>学术经历</h2><article v-for="a in player.portfolio.activities.filter(a=>a.status==='completed')" :key="a.id" class="resume-experience"><h3>{{ a.title }}</h3><p>{{ a.venue }} · {{ date(a.at) }}</p></article><p v-if="!player.portfolio.activities.some(a=>a.status==='completed')" class="empty-note">参会、报告与研究活动会逐步记录。</p></section>
   <section><h2>学生与培养规划</h2><article v-for="st in player.students" :key="st.id" class="resume-student"><ScholarPortrait :seed="st.avatarSeed" :size="43" :label="st.name+'头像'"/><div><h3>{{ st.name }} <small>{{ st.degree==='masters'?'硕士':'博士' }} · {{ st.graduatedAt?'已毕业':'在读' }}</small></h3><p>{{ st.topic }}</p><p>{{ st.plan }}</p><span>当前任务：{{ st.task?.title||'自由研究' }}</span><span>发表论文 {{ st.paper.total }} · 授权专利 {{ st.patent.total }}</span><ul v-if="st.activities.some(a=>a.status==='completed')"><li v-for="a in st.activities.filter(a=>a.status==='completed')" :key="a.id">{{ a.title }} · {{ a.venue }}</li></ul></div></article><p v-if="!player.students.length" class="empty-note">招收学生后，可在这里介绍他们的方向、成果与成长经历。</p></section><footer>以上学校、科研成果与经历均为本游戏的虚构记录。</footer>
  </article></template>
</template>
